```ts
import type { Request, Response, NextFunction } from 'express';
import jwt, {
  JsonWebTokenError,
  NotBeforeError,
  TokenExpiredError,
  JwtPayload,
} from 'jsonwebtoken';

class AuthenticationError extends Error {
  statusCode = 401;
  code = 'AUTHENTICATION_ERROR';

  constructor(message = 'Authentication failed') {
    super(message);
    this.name = 'AuthenticationError';
  }
}

class TokenValidationError extends AuthenticationError {
  constructor(message = 'Invalid token') {
    super(message);
    this.name = 'TokenValidationError';
    this.code = 'TOKEN_VALIDATION_ERROR';
  }
}

class AuthorizationError extends Error {
  statusCode = 403;
  code = 'AUTHORIZATION_ERROR';

  constructor(message = 'Forbidden') {
    super(message);
    this.name = 'AuthorizationError';
  }
}

type AuthenticatedRequest = Request & {
  auth?: {
    sub: string;
    roles?: string[];
    scope?: string;
    token: string;
    claims: JwtPayload;
  };
};

function extractBearerToken(req: Request): string {
  const header = req.headers.authorization;

  if (!header) {
    throw new AuthenticationError('Missing Authorization header');
  }

  const [scheme, token, ...rest] = header.trim().split(/\s+/);

  if (scheme !== 'Bearer' || !token || rest.length > 0) {
    throw new AuthenticationError('Malformed Authorization header');
  }

  return token;
}

function assertJwtPayload(decoded: string | JwtPayload): JwtPayload {
  if (!decoded || typeof decoded === 'string') {
    throw new TokenValidationError('Token payload is invalid');
  }

  if (typeof decoded.sub !== 'string' || decoded.sub.length === 0) {
    throw new TokenValidationError('Token subject is missing');
  }

  return decoded;
}

export function authMiddleware(req: AuthenticatedRequest, _res: Response, next: NextFunction) {
  try {
    const token = extractBearerToken(req);

    const secret = process.env.JWT_SECRET;
    if (!secret) {
      throw new Error('JWT_SECRET is not configured');
    }

    const decoded = jwt.verify(token, secret, {
      algorithms: ['HS256'],
      audience: process.env.JWT_AUDIENCE,
      issuer: process.env.JWT_ISSUER,
    });

    const claims = assertJwtPayload(decoded);

    req.auth = {
      sub: claims.sub as string,
      roles: Array.isArray(claims.roles) ? claims.roles.filter((r): r is string => typeof r === 'string') : undefined,
      scope: typeof claims.scope === 'string' ? claims.scope : undefined,
      token,
      claims,
    };

    next();
  } catch (error) {
    if (error instanceof TokenExpiredError) {
      return next(new TokenValidationError('Token expired'));
    }

    if (error instanceof NotBeforeError) {
      return next(new TokenValidationError('Token not active'));
    }

    if (error instanceof JsonWebTokenError) {
      return next(new TokenValidationError('Token invalid'));
    }

    return next(error);
  }
}
```

