```ts
import type { Request, Response, NextFunction } from "express";
import jwt, { JsonWebTokenError, TokenExpiredError } from "jsonwebtoken";
import type { AuthToken } from "../types";
import { AppError } from "../middleware/error";

const JWT_SECRET = process.env.JWT_SECRET ?? "dev-secret";

function isAuthToken(value: unknown): value is AuthToken {
  if (!value || typeof value !== "object") {
    return false;
  }

  const token = value as Record<string, unknown>;

  return (
    typeof token.sub === "string" &&
    typeof token.iat === "number" &&
    typeof token.exp === "number" &&
    typeof token.role === "string"
  );
}

export function authenticate(
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    next(new AppError("Missing authorization header", 401, "AUTH_MISSING_HEADER"));
    return;
  }

  if (!authHeader.startsWith("Bearer ")) {
    next(new AppError("Invalid authorization scheme", 401, "AUTH_INVALID_SCHEME"));
    return;
  }

  const token = authHeader.slice(7).trim();

  if (!token) {
    next(new AppError("Missing token", 401, "AUTH_MISSING_TOKEN"));
    return;
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);

    if (!isAuthToken(decoded)) {
      next(new AppError("Invalid token payload", 401, "AUTH_INVALID_PAYLOAD"));
      return;
    }

    (req as Request & { user?: AuthToken }).user = decoded;
    next();
  } catch (err) {
    if (err instanceof TokenExpiredError) {
      next(new AppError("Token expired", 401, "AUTH_TOKEN_EXPIRED"));
      return;
    }

    if (err instanceof JsonWebTokenError) {
      next(new AppError("Invalid token", 401, "AUTH_INVALID_TOKEN"));
      return;
    }

    next(err as Error);
  }
}

/**
 * Role-based access control middleware
 */
export function requireRole(...roles: string[]) {
  return (req: Request, _res: Response, next: NextFunction): void => {
    const user = (req as Request & { user?: AuthToken }).user;

    if (!user) {
      next(new AppError("Authentication required", 401, "AUTH_REQUIRED"));
      return;
    }

    if (!roles.includes(user.role)) {
      next(new AppError("Forbidden", 403, "AUTH_FORBIDDEN"));
      return;
    }

    next();
  };
}
```

