import type { Request, Response, NextFunction } from "express";
import jwt, {
  JsonWebTokenError,
  TokenExpiredError,
  type JwtPayload,
} from "jsonwebtoken";
import type { AuthToken } from "../types";
import { AppError } from "../middleware/error";

const JWT_SECRET = process.env.JWT_SECRET ?? "dev-secret";

function isAuthToken(payload: string | JwtPayload): payload is AuthToken {
  if (typeof payload === "string") {
    return false;
  }

  return (
    typeof payload.sub === "string" &&
    typeof payload.role === "string" &&
    typeof payload.iat === "number" &&
    typeof payload.exp === "number"
  );
}

export function authenticate(
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    next(new AppError("Missing authorization header", 401, "AUTH_MISSING"));
    return;
  }

  if (!authHeader.startsWith("Bearer ")) {
    next(new AppError("Invalid authorization scheme", 401, "AUTH_INVALID"));
    return;
  }

  const token = authHeader.slice(7).trim();

  if (!token) {
    next(new AppError("Missing token", 401, "AUTH_MISSING"));
    return;
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);

    if (!isAuthToken(decoded)) {
      next(new AppError("Invalid token payload", 401, "AUTH_INVALID"));
      return;
    }

    (req as any).user = decoded;
    next();
  } catch (error) {
    if (error instanceof TokenExpiredError) {
      next(new AppError("Token expired", 401, "AUTH_TOKEN_EXPIRED"));
      return;
    }

    if (error instanceof JsonWebTokenError) {
      next(new AppError("Invalid token", 401, "AUTH_INVALID"));
      return;
    }

    next(error as Error);
  }
}

/**
 * Role-based access control middleware
 */
export function requireRole(...roles: string[]) {
  return (req: Request, _res: Response, next: NextFunction): void => {
    const user = (req as any).user as AuthToken | undefined;

    if (!user) {
      next(new AppError("Authentication required", 401, "AUTH_REQUIRED"));
      return;
    }

    if (!roles.includes(user.role)) {
      next(new AppError("Forbidden", 403, "AUTH_FORBIDDEN"));
      return;
    }

    next();
  };
}
```

