export function chunk<T>(items: readonly T[], size: number): T[][] {
  if (size <= 0) {
    throw new Error("chunk size must be greater than 0");
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

export function unique<T>(items: readonly T[]): T[] {
  return [...new Set(items)];
}

export function flatten<T>(items: readonly (readonly T[])[]): T[] {
  return items.reduce<T[]>((acc, group) => {
    acc.push(...group);
    return acc;
  }, []);
}

export function intersect<T>(a: readonly T[], b: readonly T[]): T[] {
  const bSet = new Set(b);
  return unique(a.filter(item => bSet.has(item)));
}

export function groupBy<T, K extends PropertyKey>(
  items: readonly T[],
  keyFn: (item: T) => K
): Record<K, T[]> {
  return items.reduce((acc, item) => {
    const key = keyFn(item);
    (acc[key] ??= []).push(item);
    return acc;
  }, {} as Record<K, T[]>);
}

export function sortBy<T, V extends string | number>(
  items: readonly T[],
  selector: (item: T) => V
): T[] {
  return [...items].sort((a, b) => {
    const av = selector(a);
    const bv = selector(b);
    return av < bv ? -1 : av > bv ? 1 : 0;
  });
}

export function zip<A, B>(a: readonly A[], b: readonly B[]): Array<[A, B]> {
  const length = Math.min(a.length, b.length);
  const result: Array<[A, B]> = [];

  for (let i = 0; i < length; i++) {
    result.push([a[i], b[i]]);
  }

  return result;
}

export function sample<T>(items: readonly T[]): T | undefined {
  if (items.length === 0) {
    return undefined;
  }

  const index = Math.floor(Math.random() * items.length);
  return items[index];
}
```

